from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


class OpenAIResponseError(RuntimeError):
    \"\"\"Raised when a Responses API request cannot be completed safely.\"\"\"

    def __init__(self, message: str, status_code: Optional[int] = None) -> None:
        super().__init__(message)
        self.status_code = status_code


class OpenAIResponsesClient:
    \"\"\"Send private text prompts to OpenAI's Responses API.

    Prompts and API keys are never logged. API error bodies are discarded
    because they may contain request details.
    \"\"\"

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        *,
        endpoint: str = \"https://api.openai.com/v1/responses\",
        timeout: float = 60.0,
    ) -> None:
        self._api_key = api_key or os.environ.get(\"OPENAI_API_KEY\", \"\")
        if not self._api_key.strip():
            raise ValueError(\"Set OPENAI_API_KEY or pass api_key explicitly\")
        self.endpoint = endpoint
        self.timeout = timeout

    def send_prompt(
        self,
        prompt: str,
        *,
        model: str,
        instructions: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        previous_response_id: Optional[str] = None,
        store: bool = False,
    ) -> str:
        \"\"\"Send one text prompt and return the model's text response.\"\"\"
        response = self.send_request(
            prompt,
            model=model,
            instructions=instructions,
            temperature=temperature,
            max_output_tokens=max_output_tokens,
            previous_response_id=previous_response_id,
            store=store,
        )
        return self.response_text(response)

    def send_request(
        self,
        prompt: str,
        *,
        model: str,
        instructions: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        previous_response_id: Optional[str] = None,
        store: bool = False,
    ) -> dict[str, Any]:
        \"\"\"Send one text prompt and return the complete JSON response.\"\"\"
        if not isinstance(prompt, str) or not prompt:
            raise ValueError(\"prompt must be a non-empty string\")
        if not isinstance(model, str) or not model:
            raise ValueError(\"model must be a non-empty string\")

        payload: dict[str, Any] = {
            \"model\": model,
            \"input\": prompt,
            \"store\": store,
        }
        if instructions is not None:
            payload[\"instructions\"] = instructions
        if temperature is not None:
            payload[\"temperature\"] = temperature
        if max_output_tokens is not None:
            payload[\"max_output_tokens\"] = max_output_tokens
        if previous_response_id is not None:
            payload[\"previous_response_id\"] = previous_response_id

        request = Request(
            self.endpoint,
            data=json.dumps(payload, separators=(\",\", \":\")).encode(\"utf-8\"),
            headers={
                \"Authorization\": f\"Bearer {self._api_key}\",
                \"Content-Type\": \"application/json\",
                \"Accept\": \"application/json\",
                \"User-Agent\": \"openai-client-standard-library\",
            },
            method=\"POST\",
        )

        try:
            with urlopen(request, timeout=self.timeout) as response:
                response_body = response.read()
        except HTTPError as error:
            error.read()
            raise OpenAIResponseError(
                \"OpenAI API request failed\",
                status_code=error.code,
            ) from None
        except URLError:
            raise OpenAIResponseError(\"Could not reach the OpenAI API\") from None

        try:
            decoded = json.loads(response_body.decode(\"utf-8\"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            raise OpenAIResponseError(\"OpenAI API returned invalid JSON\") from None
        if not isinstance(decoded, dict):
            raise OpenAIResponseError(\"OpenAI API returned an unexpected response\")
        return decoded

    @staticmethod
    def response_text(response: dict[str, Any]) -> str:
        \"\"\"Extract the model's text from a Responses API JSON response.\"\"\"
        for output_item in response.get(\"output\", []):
            if not isinstance(output_item, dict):
                continue
            if output_item.get(\"type\") "'!= "message":
                continue
            for content_item in output_item.get("content", []):
                if not isinstance(content_item, dict):
                    continue
                if content_item.get("type") == "output_text":
                    text = content_item.get("text")
                    if isinstance(text, str):
                        return text
        raise OpenAIResponseError("The OpenAI response contained no text output")
